package net.zartra.gui;
import org.bukkit.entity.Player;
final class ConditionEvaluator { private final PlaceholderService placeholders=new PlaceholderService(); boolean test(Player p,MenuDefinition menu,ConditionEntry condition){boolean result;String value=placeholders.replace(p,menu,condition.value);try{switch(condition.type){case HAS_PERMISSION:result=p.hasPermission(value);break;case NOT_HAS_PERMISSION:result=!p.hasPermission(value);break;case HAS_LEVEL:case MIN_LEVEL:result=p.getLevel()>=Integer.parseInt(value);break;case MAX_LEVEL:result=p.getLevel()<=Integer.parseInt(value);break;case IS_OP:result=p.isOp();break;case IS_NOT_OP:result=!p.isOp();break;case GAMEMODE:result=p.getGameMode().name().equalsIgnoreCase(value);break;case WORLD:result=p.getWorld().getName().equalsIgnoreCase(value);break;case PLAYER_NAME:result=p.getName().equalsIgnoreCase(value);break;case IS_SNEAKING:result=p.isSneaking();break;case IS_FLYING:result=p.isFlying();break;case CHANCE:result=Math.random()*100D<=Double.parseDouble(value);break;default:result=false;}}catch(Exception e){result=false;}return condition.inverted?!result:result;} }
